def balanced(s):
    stack = []
    in_string = False
    escaped = False
    opening = "([{"
    closing = ")]}"
    matching = {")": "(", "]": "[", "}": "{"}

    for ch in s:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        else:
            if ch == '"':
                in_string = True
            elif ch in opening:
                stack.append(ch)
            elif ch in closing:
                if not stack or stack[-1] != matching[ch]:
                    return False
                stack.pop()

    return not in_string and not stack
